public class Main {
    public static void main(String[] args) {
        int p = 23; // small prime, illustrative only, never use tiny numbers like this in real TLS
        int g = 5;  // generator

        // --- ECDHE-style: forward secrecy ---
        int clientPrivate = 6;
        int serverEphemeralPrivate = 15; // discarded the instant this session ends

        int clientPublic = modPow(g, clientPrivate, p);
        int serverEphemeralPublic = modPow(g, serverEphemeralPrivate, p);

        int clientSharedSecret = modPow(serverEphemeralPublic, clientPrivate, p);
        int serverSharedSecret = modPow(clientPublic, serverEphemeralPrivate, p);
        System.out.println("ECDHE: client-derived session key = " + clientSharedSecret);
        System.out.println("ECDHE: server-derived session key = " + serverSharedSecret);
        System.out.println("ECDHE: both sides agree = " + (clientSharedSecret == serverSharedSecret));

        // Years later, an attacker steals the server's separate, long-term signing key.
        int serverLongTermKey = 999;
        int attackerAttempt = modPow(clientPublic, serverLongTermKey % (p - 1), p);
        System.out.println("Attacker using the long-term key gets: " + attackerAttempt
                + " (matches real session key: " + (attackerAttempt == clientSharedSecret) + ")");

        // --- RSA-style: no forward secrecy ---
        int preMasterSecret = 42;
        int cipherText = preMasterSecret ^ serverLongTermKey; // simple reversible stand-in for "encrypted with the server's key"
        System.out.println("RSA-style: pre-master secret sent as ciphertext " + cipherText);

        int attackerRecoveredSecret = cipherText ^ serverLongTermKey; // same key that was stolen
        System.out.println("Attacker using the SAME stolen long-term key recovers: " + attackerRecoveredSecret
                + " (matches original pre-master secret: " + (attackerRecoveredSecret == preMasterSecret) + ")");
    }

    static int modPow(int base, int exponent, int modulus) {
        int result = 1;
        base = base % modulus;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % modulus;
            }
            exponent >>= 1;
            base = (base * base) % modulus;
        }
        return result;
    }
}

